/* examen maatschappijkunde */
{v:'Wat is het verschil tussen de Eerste en de Tweede Kamer?',o:['alleen de Tweede Kamer kan wetten wijzigen','de Eerste Kamer heeft twee keer zoveel leden','de leden van de Tweede Kamer worden niet gekozen','de Eerste Kamer vergadert elke dag, de Tweede niet'],g:0,u:'De Tweede Kamer (150 leden) heeft het recht van amendement en initiatief. De Eerste Kamer (75 leden) toetst.',t:'examen-mk',n:2},
{v:'Wat is het recht van interpellatie?',o:['een Kamerlid roept een minister ter verantwoording','een minister mag een lastig Kamerlid ontslaan','een gewone burger mag zelf een wet indienen bij de Kamer','de koning mag zonder overleg een minister benoemen'],g:0,u:'Met een interpellatie vraagt een Kamerlid een apart debat aan om een minister te bevragen.',t:'examen-mk',n:4},
{v:'Wat is een parlementaire enquête?',o:['een zwaar onderzoek van de Kamer, met getuigen onder ede','een peiling onder alle kiezers vlak voor de verkiezingen','een vragenlijst die nieuwe Kamerleden moeten invullen','een lang debat over de begroting op Prinsjesdag'],g:0,u:'Het zwaarste middel van de Kamer. Voorbeeld: de enquête naar de aardgaswinning in Groningen.',t:'examen-mk',n:4},
{v:'Wat is een ideologie?',o:['een samenhangend geheel van ideeën over de samenleving','het verkiezingsprogramma van één partij voor één keer','een wetenschappelijk onderzoek naar het gedrag van kiezers','een wet die bepaalt hoe politieke partijen moeten werken'],g:0,u:'Liberalisme, socialisme en christendemocratie zijn ideologieën. Partijen bouwen hun programma erop.',t:'examen-mk',n:3},
{v:'Welke waarde staat centraal in het liberalisme?',o:['individuele vrijheid','gelijkheid door een grote overheid','naastenliefde vanuit het geloof','bescherming van de eigen cultuur'],g:0,u:'Liberalen willen zo veel mogelijk vrijheid voor het individu en een beperkte overheid.',t:'examen-mk',n:3},
{v:'Welke waarde staat centraal in het socialisme?',o:['gelijkheid en solidariteit','zo weinig mogelijk overheid','de vrije markt zonder regels','tradities en gezag'],g:0,u:'Socialisten willen kleinere verschillen in inkomen en macht, vaak met een actieve overheid.',t:'examen-mk',n:3},
{v:'Wat is het verschil tussen preventief en repressief optreden van de politie?',o:['preventief is voorkomen, repressief is achteraf optreden','preventief is straffen, repressief is voorlichting geven','preventief en repressief betekenen precies hetzelfde','repressief optreden mag alleen tegen jongeren onder de 18'],g:0,u:'Surveilleren en voorlichten is preventief. Aanhouden na een inbraak is repressief.',t:'examen-mk',n:2},
{v:'Wat is een vrijspraak?',o:['het bewijs overtuigt de rechter niet, de verdachte gaat vrij','de verdachte krijgt een lage straf omdat hij spijt heeft','de officier van justitie besluit de zaak te laten vallen','de verdachte bekent alles en krijgt daarom geen straf'],g:0,u:'Bij vrijspraak is niet bewezen dat de verdachte het feit heeft gepleegd.',t:'examen-mk',n:2},
{v:'Wat is een voorwaardelijke straf?',o:['een straf die pas geldt als je weer in de fout gaat','een straf die altijd direct wordt uitgevoerd','een straf die de verdachte zelf mag uitkiezen','een straf die zonder tussenkomst van een rechter komt'],g:0,u:'Binnen een proeftijd moet je je houden aan de voorwaarden. Doe je dat niet, dan moet je de straf alsnog uitzitten.',t:'examen-mk',n:2},
{v:'Wat is de rol van slachtofferhulp?',o:['slachtoffers steunen na een misdrijf','daders begeleiden als ze hun straf hebben uitgezeten','de politie helpen bij het opsporen van verdachten','boetes innen voor de staat na een verkeersovertreding'],g:0,u:'Slachtofferhulp Nederland helpt met praktische, juridische en emotionele steun.',t:'examen-mk',n:1},
{v:'Waarom stijgt het aantal geregistreerde fietsdiefstallen soms als de politie campagne voert?',o:['meer mensen doen dan aangifte','er worden dan meer fietsen gestolen','de politie telt dubbel','fietsen worden duurder'],g:0,u:'Geregistreerde criminaliteit hangt af van de aangiftebereidheid. Meer aangiften betekent niet altijd meer diefstal.',t:'examen-mk',n:4},
{v:'Wat is sociale ongelijkheid?',o:['groepen verschillen in inkomen, macht en kansen','iedereen verdient hetzelfde, wat hij ook doet','mensen verschillen van elkaar in lengte en gewicht','een land heeft meer mannen dan vrouwen als inwoners'],g:0,u:'Ongelijkheid gaat over de verdeling van schaarse zaken zoals geld, macht, kennis en aanzien.',t:'examen-mk',n:3},
{v:'Wat is sociale mobiliteit?',o:['stijgen of dalen op de maatschappelijke ladder','vaak verhuizen van de ene stad naar de andere','veel vrienden en volgers hebben op sociale media','veel reizen met het openbaar vervoer door het land'],g:0,u:'Een kind van ouders met een laag inkomen dat later arts wordt, maakt een stijging op de sociale ladder.',t:'examen-mk',n:4}
